    // ── LIFECYCLE ──
    protected override async Task OnInitializedAsync()
    {
        maTruongBo     = await BrowserStorageService.GetMaTruongBoAsync(JSRuntime);
        selectedNamHoc = await BrowserStorageService.GetItem(JS, "selectedNamHoc");
        selectedCapHoc = await BrowserStorageService.GetItem(JS, "selectedLevel");
        tenTruong      = await BrowserStorageService.GetItem(JS, "tenTruong") ?? "Trường học";

        await LoadMeta();
        await LoadData();
    }

    // ── LOAD KHỐI / LỚP / HỌC SINH META ──
    private async Task LoadMeta()
    {
        if (string.IsNullOrEmpty(maTruongBo)) return;
        try
        {
            var taskKhoi = TruongService.hGetDanhSachKhoi(maTruongBo, selectedCapHoc ?? "1");
            var taskLop  = TruongService.hGetDanhSachLop(maTruongBo, selectedCapHoc ?? "1", selectedNamHoc ?? "");
            var taskHs   = TruongService.hGetDanhSachHocSinh(maTruongBo, selectedCapHoc ?? "1", selectedNamHoc ?? "");

            await Task.WhenAll(taskKhoi, taskLop, taskHs);

            KhoiList        = taskKhoi.Result;
            AllLopList      = taskLop.Result;
            FilteredLopList = AllLopList.ToList();
            AllHocSinh      = taskHs.Result;
        }
        catch (Exception ex)
        {
            Console.WriteLine($"LoadMeta error: {ex.Message}");
        }
    }

    // ── LOAD ĐƠN NGHỈ PHÉP ──
    private async Task LoadData()
    {
        if (string.IsNullOrEmpty(maTruongBo) || string.IsNullOrEmpty(selectedNamHoc)) return;

        isLoading = true;
        StateHasChanged();

        try
        {
            int? idLopFilter = selectedIdLop.HasValue && selectedIdLop > 0 ? selectedIdLop : null;

            var rawList = await TruongService.hGetDonNghiPhep(
                namHoc : selectedNamHoc,
                idLop  : idLopFilter);

            // Lọc theo trường
            rawList = rawList.Where(d => d.MaTruongBo == maTruongBo).ToList();

            // Build ViewModel: join tên học sinh & tên lớp
            var hsDict  = AllHocSinh.ToDictionary(h => h.MaHsSo, h => h);
            var lopDict = AllLopList.ToDictionary(l => l.IdLopBo, l => l.TenLop);

            DonList = rawList.Select(d =>
            {
                var vm = new DonNghiVM
                {
                    IdDon            = d.IdDon,
                    MaHsSo           = d.MaHsSo,
                    NgayBatDau       = d.NgayBatDau,
                    NgayKetThuc      = d.NgayKetThuc,
                    LyDoNghiHoc      = d.LyDoNghiHoc,
                    IdTrangThai      = d.IdTrangThai,
                    IdLop            = d.IdLop,
                    IsBuoiSang       = d.IsBuoiSang,
                    IsBuoiChieu      = d.IsBuoiChieu,
                    IsDongBo         = d.IsDongBo,
                    MaTruongBo       = d.MaTruongBo,
                    DonNghiPhepCode  = d.DonNghiPhepCode,
                    NamHoc           = d.NamHoc,
                };

                if (!string.IsNullOrEmpty(d.MaHsSo) && hsDict.TryGetValue(d.MaHsSo, out var hs))
                    vm.TenHocSinh = hs.HoTen;
                else
                    vm.TenHocSinh = d.MaHsSo ?? "—";

                if (d.IdLop.HasValue && lopDict.TryGetValue(d.IdLop.Value, out var tenLop))
                    vm.TenLop = tenLop;
                else
                    vm.TenLop = "—";

                return vm;
            }).ToList();

            ApplyFilter();
        }
        catch (Exception ex)
        {
            Console.WriteLine($"LoadData error: {ex.Message}");
            await ShowToast("Lỗi tải dữ liệu đơn nghỉ phép!", "error");
        }
        finally
        {
            isLoading = false;
            StateHasChanged();
        }
    }

    // ── FILTER ──
    private void ApplyFilter()
    {
        if (DonList == null) { FilteredList = new(); DisplayList = new(); StateHasChanged(); return; }

        var result = DonList.AsEnumerable();

        // Lọc theo lớp
        if (selectedIdLop.HasValue && selectedIdLop > 0)
            result = result.Where(d => d.IdLop == selectedIdLop);

        // Lọc theo trạng thái
        if (filterTrangThai > 0)
            result = result.Where(d => d.IdTrangThai == filterTrangThai);

        // Lọc theo ngày: ngày chọn phải nằm trong khoảng [NgayBatDau, NgayKetThuc]
        if (filterDate.HasValue)
        {
            var d0 = filterDate.Value.Date;
            result = result.Where(d =>
                d.NgayBatDau.HasValue &&
                d0 >= d.NgayBatDau.Value.Date &&
                (!d.NgayKetThuc.HasValue || d0 <= d.NgayKetThuc.Value.Date));
        }

        // Tìm kiếm text
        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var t = searchTerm.Trim();
            result = result.Where(d =>
                (d.TenHocSinh?.Contains(t, StringComparison.OrdinalIgnoreCase) == true) ||
                (d.LyDoNghiHoc?.Contains(t, StringComparison.OrdinalIgnoreCase) == true) ||
                (d.MaHsSo?.Contains(t, StringComparison.OrdinalIgnoreCase) == true));
        }

        FilteredList = result
            .OrderByDescending(d => d.IdTrangThai == 1)
            .ThenByDescending(d => d.NgayBatDau)
            .ToList();

        currentPage = 1;
        BuildPagedList();
        StateHasChanged();
    }

    private void BuildPagedList()
    {
        DisplayList = FilteredList
            .Skip((currentPage - 1) * pageSize)
            .Take(pageSize)
            .ToList();
    }

    private void OnPageChanged(int page)
    {
        currentPage = page;
        BuildPagedList();
        StateHasChanged();
    }

    private void ClearDateFilter()
    {
        filterDateStr = "";
        filterDate    = null;
        ApplyFilter();
        StateHasChanged();
    }

    private void OnDateStrChanged(ChangeEventArgs e)
    {
        filterDateStr = e.Value?.ToString() ?? "";
        if (!string.IsNullOrEmpty(filterDateStr) && DateTime.TryParse(filterDateStr, out var dt))
            filterDate = dt;
        else
            filterDate = null;
        ApplyFilter();
        StateHasChanged();
    }

    private void ApplyFilterFromDateStr()
    {
        if (!string.IsNullOrEmpty(filterDateStr) && DateTime.TryParse(filterDateStr, out var dt))
            filterDate = dt;
        else
            filterDate = null;
        ApplyFilter();
    }

    private async Task FocusDateInput()
    {
        await JS.InvokeVoidAsync("eval",
            "var el=document.querySelector('.dnp-date-input'); if(el){ el.showPicker ? el.showPicker() : el.focus(); }");
    }

    private void OnPageSizeChanged(ChangeEventArgs e)
    {
        if (int.TryParse(e.Value?.ToString(), out var sz) && sz > 0)
        {
            pageSize = sz;
            currentPage = 1;
            BuildPagedList();
            StateHasChanged();
        }
    }

    private void ToggleLydo(long idDon)
    {
        if (expandedLydoIds.Contains(idDon))
            expandedLydoIds.Remove(idDon);
        else
            expandedLydoIds.Add(idDon);
    }

    // ── FILTER EVENTS ──
    private async Task OnKhoiChanged(ChangeEventArgs e)
    {
        selectedMaKhoi  = e.Value?.ToString() ?? "";
        selectedIdLop   = null;
        FilteredLopList = string.IsNullOrEmpty(selectedMaKhoi)
            ? AllLopList.ToList()
            : AllLopList.Where(l => l.MaKhoiBo == selectedMaKhoi).ToList();
        ApplyFilter();
        await Task.CompletedTask;
    }

    private async Task OnLopChanged(ChangeEventArgs e)
    {
        selectedIdLop = int.TryParse(e.Value?.ToString(), out var id) ? id : null;
        ApplyFilter();
        await Task.CompletedTask;
    }

    // ── DETAIL MODAL ──
    private void OpenDetail(DonNghiVM item)
    {
        detailItem      = item;
        showDetailModal = true;
    }

    private void CloseDetailModal()
    {
        showDetailModal = false;
        detailItem      = null;
    }

    // ── CONFIRM DIALOG ──
    private void AskConfirm(DonNghiVM item, ActionType action)
    {
        confirmItem   = item;
        confirmAction = action;
        showDetailModal = false;

        switch (action)
        {
            case ActionType.Approve:
                confirmTitle       = "Xác nhận duyệt đơn";
                confirmMessage     = "Bạn có chắc muốn ĐỒNG Ý đơn nghỉ phép này?";
                confirmIcon        = "check_circle";
                confirmHeaderClass = "header-approve";
                confirmBtnClass    = "btn-action btn-approve";
                confirmBtnText     = "Đồng ý";
                break;
            case ActionType.Reject:
                confirmTitle       = "Xác nhận không duyệt";
                confirmMessage     = "Bạn có chắc muốn KHÔNG DUYỆT đơn nghỉ phép này?";
                confirmIcon        = "cancel";
                confirmHeaderClass = "header-reject";
                confirmBtnClass    = "btn-action btn-reject";
                confirmBtnText     = "Không duyệt";
                break;
            case ActionType.Cancel:
                confirmTitle       = "Xác nhận hủy đơn";
                confirmMessage     = "Bạn có chắc muốn HỦY đơn nghỉ phép này?";
                confirmIcon        = "block";
                confirmHeaderClass = "header-cancel";
                confirmBtnClass    = "btn-action btn-cancel";
                confirmBtnText     = "Hủy đơn";
                break;
        }

        showConfirmDialog = true;
    }

    private void CloseConfirmDialog()
    {
        showConfirmDialog = false;
        confirmItem       = null;
    }

    private async Task ExecuteConfirm()
    {
        if (confirmItem == null) return;
        isProcessing = true;
        StateHasChanged();

        try
        {
            int newTrangThai = confirmAction switch
            {
                ActionType.Approve => 2,
                ActionType.Reject  => 3,
                ActionType.Cancel  => 3,
                _                  => confirmItem.IdTrangThai ?? 1,
            };

            var updateModel = new DonNghiPhepDTO
            {
                IdDon       = confirmItem.IdDon,
                IdTrangThai = newTrangThai,
            };

            await TruongService.hUpdateDonNghiPhep(updateModel);

            // Cập nhật local list
            confirmItem.IdTrangThai = newTrangThai;
            ApplyFilter();

            string msg = confirmAction switch
            {
                ActionType.Approve => "Đã duyệt đơn thành công!",
                ActionType.Reject  => "Đã từ chối đơn thành công!",
                ActionType.Cancel  => "Đã hủy đơn thành công!",
                _                  => "Cập nhật thành công!",
            };

            await ShowToast(msg, "success");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"ExecuteConfirm error: {ex.Message}");
            await ShowToast("Xử lý thất bại, vui lòng thử lại!", "error");
        }
        finally
        {
            isProcessing      = false;
            showConfirmDialog = false;
            confirmItem       = null;
            StateHasChanged();
        }
    }

