    private string FormatNgayNghi(DonNghiVM d)
    {
        var tu  = d.NgayBatDau?.ToString("dd/MM/yyyy") ?? "?";
        var den = d.NgayKetThuc?.ToString("dd/MM/yyyy") ?? "?";
        return tu == den ? $"Ngày {tu}" : $"Từ {tu} đến {den}";
    }

    // ── TOAST (dùng shared component) ──
    private async Task ShowToast(string msg, string type = "success")
    {
        _toastCts?.Cancel();
        _toastCts     = new System.Threading.CancellationTokenSource();
        _toastMessage = msg;
        _toastType    = type;
        _toastVisible = true;
        StateHasChanged();
        try
        {
            await Task.Delay(3500, _toastCts.Token);
            _toastVisible = false;
            StateHasChanged();
        }
        catch (TaskCanceledException) { }
    }

